class Resource:
    def __init__(self, name, fail_on, log):
        self.name, self.fail_on, self.log = name, fail_on, log

    def __enter__(self):
        if self.name == self.fail_on:
            raise RuntimeError(f"cannot open {self.name}")
        self.log.append(f"open {self.name}")
        return self

    def __exit__(self, exc_type, exc, tb):
        self.log.append(f"close {self.name}")
        return False


def check_cleanup(names, fail_on):
    log = []
    try:
        run_steps(names, fail_on, log)
    except RuntimeError as e:
        log.append(f"error: {e}")
    return log

