public sealed class Resource : IDisposable
{
    private readonly string _name;
    private readonly List<string> _log;

    public Resource(string name, string failOn, List<string> log)
    {
        if (name == failOn) throw new InvalidOperationException($"cannot open {name}");
        _name = name;
        _log = log;
        log.Add($"open {name}");
    }

    public void Dispose() => _log.Add($"close {_name}");
}

